-- 4. weapon skills the gear donor has by race, for exactly the new pair (computed from the live table)
DELETE FROM `playercreateinfo_skills` WHERE `comment` LIKE 'charfix %';
DROP TEMPORARY TABLE IF EXISTS `ov_charfix_donor`;
CREATE TEMPORARY TABLE `ov_charfix_donor` (`race` TINYINT UNSIGNED, `class` TINYINT UNSIGNED, `donor` TINYINT UNSIGNED, PRIMARY KEY (`race`, `class`));
SELECT 1 << (d.`race` - 1), 1 << (d.`class` - 1), s.`skill`, MAX(s.`rank`), CONCAT('charfix ', d.`race`, '/', d.`class`, ' from ', d.`donor`)
FROM `ov_charfix_donor` d
JOIN `playercreateinfo_skills` s
  ON s.`classMask` & (1 << (d.`class` - 1)) AND s.`raceMask` <> 0 AND s.`raceMask` & (1 << (d.`donor` - 1))
WHERE NOT (s.`raceMask` & (1 << (d.`race` - 1)))
  AND (s.`comment` IS NULL OR s.`comment` NOT LIKE 'charfix %')
  AND NOT EXISTS (SELECT 1 FROM `playercreateinfo_skills` x WHERE x.`skill` = s.`skill`
                  AND (x.`raceMask` = 0 OR x.`raceMask` & (1 << (d.`race` - 1)))
                  AND (x.`classMask` = 0 OR x.`classMask` & (1 << (d.`class` - 1))))
GROUP BY d.`race`, d.`class`, d.`donor`, s.`skill`;
DROP TEMPORARY TABLE `ov_charfix_donor`;

