-- 6. class quests for the new pairs (restored from the saved originals first, so a re-run adds nothing twice)
CREATE TABLE IF NOT EXISTS `ov_charfix_quest_races` (`ID` INT UNSIGNED NOT NULL PRIMARY KEY, `AllowableRaces` INT UNSIGNED NOT NULL) COMMENT 'charfix_world.sql: quest_template.AllowableRaces before charfix';
UPDATE `quest_template` q JOIN `ov_charfix_quest_races` b ON b.`ID` = q.`ID` SET q.`AllowableRaces` = b.`AllowableRaces`;
SELECT q.`ID`, q.`AllowableRaces` FROM `quest_template` q JOIN `quest_template_addon` a ON a.`ID` = q.`ID`
WHERE q.`AllowableRaces` <> 0 AND a.`AllowableClasses` <> 0 AND (
   ((a.`AllowableClasses` & 4) <> 0 AND (a.`AllowableClasses` & 443) = 0 AND (q.`AllowableRaces` & 1101) <> 0 AND (q.`AllowableRaces` & 690) = 0 AND (q.`AllowableRaces` & 1) = 0)
 OR ((a.`AllowableClasses` & 144) <> 0 AND (a.`AllowableClasses` & 365) = 0 AND (q.`AllowableRaces` & 690) <> 0 AND (q.`AllowableRaces` & 1101) = 0 AND (q.`AllowableRaces` & 2) = 0)
 OR ((a.`AllowableClasses` & 448) <> 0 AND (a.`AllowableClasses` & 63) = 0 AND (q.`AllowableRaces` & 1101) <> 0 AND (q.`AllowableRaces` & 690) = 0 AND (q.`AllowableRaces` & 4) = 0)
 OR ((a.`AllowableClasses` & 384) <> 0 AND (a.`AllowableClasses` & 1085) = 0 AND (q.`AllowableRaces` & 1101) <> 0 AND (q.`AllowableRaces` & 690) = 0 AND (q.`AllowableRaces` & 8) = 0)
 OR ((a.`AllowableClasses` & 4) <> 0 AND (a.`AllowableClasses` & 441) = 0 AND (q.`AllowableRaces` & 690) <> 0 AND (q.`AllowableRaces` & 1101) = 0 AND (q.`AllowableRaces` & 16) = 0)
 OR ((a.`AllowableClasses` & 410) <> 0 AND (a.`AllowableClasses` & 1125) = 0 AND (q.`AllowableRaces` & 690) <> 0 AND (q.`AllowableRaces` & 1101) = 0 AND (q.`AllowableRaces` & 32) = 0)
 OR ((a.`AllowableClasses` & 20) <> 0 AND (a.`AllowableClasses` & 425) = 0 AND (q.`AllowableRaces` & 1101) <> 0 AND (q.`AllowableRaces` & 690) = 0 AND (q.`AllowableRaces` & 64) = 0)
 OR ((a.`AllowableClasses` & 1280) <> 0 AND (a.`AllowableClasses` & 253) = 0 AND (q.`AllowableRaces` & 690) <> 0 AND (q.`AllowableRaces` & 1101) = 0 AND (q.`AllowableRaces` & 128) = 0)
 OR ((a.`AllowableClasses` & 1) <> 0 AND (a.`AllowableClasses` & 446) = 0 AND (q.`AllowableRaces` & 690) <> 0 AND (q.`AllowableRaces` & 1101) = 0 AND (q.`AllowableRaces` & 512) = 0)
 OR ((a.`AllowableClasses` & 264) <> 0 AND (a.`AllowableClasses` & 247) = 0 AND (q.`AllowableRaces` & 1101) <> 0 AND (q.`AllowableRaces` & 690) = 0 AND (q.`AllowableRaces` & 1024) = 0));
UPDATE `quest_template` q JOIN `quest_template_addon` a ON a.`ID` = q.`ID` SET q.`AllowableRaces` = q.`AllowableRaces` | 1
WHERE q.`AllowableRaces` <> 0 AND a.`AllowableClasses` <> 0 AND (a.`AllowableClasses` & 4) <> 0 AND (a.`AllowableClasses` & 443) = 0 AND (q.`AllowableRaces` & 1101) <> 0 AND (q.`AllowableRaces` & 690) = 0 AND (q.`AllowableRaces` & 1) = 0; -- Human
UPDATE `quest_template` q JOIN `quest_template_addon` a ON a.`ID` = q.`ID` SET q.`AllowableRaces` = q.`AllowableRaces` | 2
WHERE q.`AllowableRaces` <> 0 AND a.`AllowableClasses` <> 0 AND (a.`AllowableClasses` & 144) <> 0 AND (a.`AllowableClasses` & 365) = 0 AND (q.`AllowableRaces` & 690) <> 0 AND (q.`AllowableRaces` & 1101) = 0 AND (q.`AllowableRaces` & 2) = 0; -- Orc
UPDATE `quest_template` q JOIN `quest_template_addon` a ON a.`ID` = q.`ID` SET q.`AllowableRaces` = q.`AllowableRaces` | 4
WHERE q.`AllowableRaces` <> 0 AND a.`AllowableClasses` <> 0 AND (a.`AllowableClasses` & 448) <> 0 AND (a.`AllowableClasses` & 63) = 0 AND (q.`AllowableRaces` & 1101) <> 0 AND (q.`AllowableRaces` & 690) = 0 AND (q.`AllowableRaces` & 4) = 0; -- Dwarf
UPDATE `quest_template` q JOIN `quest_template_addon` a ON a.`ID` = q.`ID` SET q.`AllowableRaces` = q.`AllowableRaces` | 8
WHERE q.`AllowableRaces` <> 0 AND a.`AllowableClasses` <> 0 AND (a.`AllowableClasses` & 384) <> 0 AND (a.`AllowableClasses` & 1085) = 0 AND (q.`AllowableRaces` & 1101) <> 0 AND (q.`AllowableRaces` & 690) = 0 AND (q.`AllowableRaces` & 8) = 0; -- Night Elf
UPDATE `quest_template` q JOIN `quest_template_addon` a ON a.`ID` = q.`ID` SET q.`AllowableRaces` = q.`AllowableRaces` | 16
WHERE q.`AllowableRaces` <> 0 AND a.`AllowableClasses` <> 0 AND (a.`AllowableClasses` & 4) <> 0 AND (a.`AllowableClasses` & 441) = 0 AND (q.`AllowableRaces` & 690) <> 0 AND (q.`AllowableRaces` & 1101) = 0 AND (q.`AllowableRaces` & 16) = 0; -- Undead
UPDATE `quest_template` q JOIN `quest_template_addon` a ON a.`ID` = q.`ID` SET q.`AllowableRaces` = q.`AllowableRaces` | 32
WHERE q.`AllowableRaces` <> 0 AND a.`AllowableClasses` <> 0 AND (a.`AllowableClasses` & 410) <> 0 AND (a.`AllowableClasses` & 1125) = 0 AND (q.`AllowableRaces` & 690) <> 0 AND (q.`AllowableRaces` & 1101) = 0 AND (q.`AllowableRaces` & 32) = 0; -- Tauren
UPDATE `quest_template` q JOIN `quest_template_addon` a ON a.`ID` = q.`ID` SET q.`AllowableRaces` = q.`AllowableRaces` | 64
WHERE q.`AllowableRaces` <> 0 AND a.`AllowableClasses` <> 0 AND (a.`AllowableClasses` & 20) <> 0 AND (a.`AllowableClasses` & 425) = 0 AND (q.`AllowableRaces` & 1101) <> 0 AND (q.`AllowableRaces` & 690) = 0 AND (q.`AllowableRaces` & 64) = 0; -- Gnome
UPDATE `quest_template` q JOIN `quest_template_addon` a ON a.`ID` = q.`ID` SET q.`AllowableRaces` = q.`AllowableRaces` | 128
WHERE q.`AllowableRaces` <> 0 AND a.`AllowableClasses` <> 0 AND (a.`AllowableClasses` & 1280) <> 0 AND (a.`AllowableClasses` & 253) = 0 AND (q.`AllowableRaces` & 690) <> 0 AND (q.`AllowableRaces` & 1101) = 0 AND (q.`AllowableRaces` & 128) = 0; -- Troll
UPDATE `quest_template` q JOIN `quest_template_addon` a ON a.`ID` = q.`ID` SET q.`AllowableRaces` = q.`AllowableRaces` | 512
WHERE q.`AllowableRaces` <> 0 AND a.`AllowableClasses` <> 0 AND (a.`AllowableClasses` & 1) <> 0 AND (a.`AllowableClasses` & 446) = 0 AND (q.`AllowableRaces` & 690) <> 0 AND (q.`AllowableRaces` & 1101) = 0 AND (q.`AllowableRaces` & 512) = 0; -- Blood Elf
UPDATE `quest_template` q JOIN `quest_template_addon` a ON a.`ID` = q.`ID` SET q.`AllowableRaces` = q.`AllowableRaces` | 1024
WHERE q.`AllowableRaces` <> 0 AND a.`AllowableClasses` <> 0 AND (a.`AllowableClasses` & 264) <> 0 AND (a.`AllowableClasses` & 247) = 0 AND (q.`AllowableRaces` & 1101) <> 0 AND (q.`AllowableRaces` & 690) = 0 AND (q.`AllowableRaces` & 1024) = 0; -- Draenei
